//! Default color mapping (lets-plot `DefaultMapperProviderUtil.createColorMapperProvider`):
//! discrete data -> ColorBrewer `Set1` (more than 9 categories: extra colors
//! generated by shifting HCL lightness, `PaletteUtil.generateColors`); continuous
//! data -> a LAB gradient from `#132B43` to `#56B1F7`. Missing values are gray.

use super::color_space::{Hcl, Lab, hcl_from_rgb, lab_from_rgb, rgb_from_hcl, rgb_from_lab};
use super::{StyleMapper, linear};
use crate::data::ContinuousColumn;
use crate::scene::{Color, PerItem};
use crate::style::{StyleValues, ValueKind};

/// lets-plot `ColorMapperDefaults.NA_VALUE` (`Color.GRAY`).
pub const NA_COLOR: Color = Color::rgb(0x80, 0x80, 0x80);
/// lets-plot `Gradient.DEF_LOW`.
pub const GRADIENT_LOW: Color = Color::rgb(0x13, 0x2b, 0x43);
/// lets-plot `Gradient.DEF_HIGH`.
pub const GRADIENT_HIGH: Color = Color::rgb(0x56, 0xb1, 0xf7);
/// ColorBrewer Set1 (9 colors); smaller sets are its prefixes.
const SET1: [Color; 9] = [
    Color::rgb(0xe4, 0x1a, 0x1c),
    Color::rgb(0x37, 0x7e, 0xb8),
    Color::rgb(0x4d, 0xaf, 0x4a),
    Color::rgb(0x98, 0x4e, 0xa3),
    Color::rgb(0xff, 0x7f, 0x00),
    Color::rgb(0xff, 0xff, 0x33),
    Color::rgb(0xa6, 0x56, 0x28),
    Color::rgb(0xf7, 0x81, 0xbf),
    Color::rgb(0x99, 0x99, 0x99),
];
/// ColorBrewer sets start at 3 colors (`ColorPalette.MIN_COLOR_SET_SIZE`).
const MIN_SET_SIZE: usize = 3;

/// The default mapper of `color` and `fill`.
#[derive(Debug, Clone, PartialEq)]
pub struct DefaultColorMapper {
    /// Color of missing and out-of-domain values (`na_value`).
    pub na: Color,
}

impl StyleMapper for DefaultColorMapper {
    fn name(&self) -> &'static str {
        "color_default"
    }

    fn value_kind(&self) -> ValueKind {
        ValueKind::Color
    }

    fn map_continuous(&self, column: &ContinuousColumn, domain: (f64, f64)) -> StyleValues {
        let (low, high) = (lab_from_rgb(GRADIENT_LOW), lab_from_rgb(GRADIENT_HIGH));
        let l = linear(domain, (low.l, high.l));
        let a = linear(domain, (low.a, high.a));
        let b = linear(domain, (low.b, high.b));
        let colors = (0..column.len())
            .map(|row| match column.get(row) {
                // lets-plot `gradientLAB`: outside the domain -> NA.
                Some(value) if value >= domain.0 && value <= domain.1 => rgb_from_lab(Lab {
                    l: l(value),
                    a: a(value),
                    b: b(value),
                }),
                _ => self.na,
            })
            .collect();
        StyleValues::Colors(PerItem::Varying(colors))
    }

    fn map_discrete(&self, indices: &[Option<usize>], level_count: usize) -> StyleValues {
        let palette = discrete_palette(level_count);
        let colors = indices
            .iter()
            .map(|index| index.map_or(self.na, |index| palette[index % palette.len()]))
            .collect();
        StyleValues::Colors(PerItem::Varying(colors))
    }
}

/// Colors for `count` categories (lets-plot `ColorBrewerMapperProvider` with the
/// default qualitative scheme and `PaletteOverflow.AUTO`).
pub fn discrete_palette(count: usize) -> Vec<Color> {
    let base = &SET1[..count.clamp(MIN_SET_SIZE, SET1.len())];
    if count <= base.len() {
        return base.to_vec();
    }
    generate_colors(base, count)
}

/// lets-plot `PaletteUtil.generateColors`: extra colors cycle through the base hues
/// with the HCL lightness moved by +/-15, +/-30, ... (wrapping within 10..90).
pub(super) fn generate_colors(base: &[Color], count: usize) -> Vec<Color> {
    const MIN: f64 = 10.0;
    const RANGE: f64 = 80.0;
    const STEP: f64 = 15.0;
    let hcl: Vec<Hcl> = base.iter().map(|color| hcl_from_rgb(*color)).collect();
    let mut colors = base.to_vec();
    for index in 0..count - base.len() {
        let source = hcl[index % hcl.len()];
        let round = index / hcl.len();
        let magnitude = ((round / 2 + 1) as f64) * STEP;
        let sign = if round % 2 == 0 { 1.0 } else { -1.0 };
        let lightness = ((source.l + sign * magnitude - MIN) % RANGE + RANGE) % RANGE + MIN;
        colors.push(rgb_from_hcl(Hcl {
            l: lightness,
            ..source
        }));
    }
    colors
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn small_palettes_are_set1_prefixes() {
        assert_eq!(discrete_palette(2), SET1[..3]);
        assert_eq!(discrete_palette(5), SET1[..5]);
        assert_eq!(discrete_palette(12).len(), 12);
        assert_eq!(discrete_palette(12)[..9], SET1);
    }

    #[test]
    fn gradient_ends_are_the_lets_plot_colors_and_outside_is_gray() {
        let column = ContinuousColumn::from_options(vec![Some(0.0), Some(1.0), Some(2.0), None]);
        let StyleValues::Colors(PerItem::Varying(colors)) =
            DefaultColorMapper { na: NA_COLOR }.map_continuous(&column, (0.0, 1.0))
        else {
            panic!("expected varying colors");
        };
        assert_eq!(colors[0], GRADIENT_LOW);
        assert_eq!(colors[1], GRADIENT_HIGH);
        assert_eq!(colors[2], NA_COLOR);
        assert_eq!(colors[3], NA_COLOR);
    }
}
